(1141590, 141730, 28619, '<td valign="top">Wow, beautiful.  The standard in this challenge is just incredible and this is one of my favourites so far.<br/> <br/>The reflection is an unnecessary distraction for me though, I would like it better if it wasn''t there to keep the mystery of who the girl is and what she looks like.<br/> <br/>Still, a lovely shot and worth a 9 in anyone''s book I reckon.</td>', 'Wow, beautiful.  The standard in this challenge is just incredible and this is one of my favourites so far. The reflection is an unnecessary distraction for me though, I would like it better if it wasn''t there to keep the mystery of who the girl is and what she looks like. Still, a lovely shot and worth a 9 in anyone''s book I reckon.', '2005-01-31 02:48:25.000000', NULL, 1),
(1141592, 141875, 25655, '<td valign="top">I wish I could see more details of that castle in the back. Just out of curiosity.<br/>The light line is wonderful.<br/>Nicely done.</td>', 'I wish I could see more details of that castle in the back. Just out of curiosity.The light line is wonderful.Nicely done.', '2005-01-31 02:50:29.000000', NULL, 1),
(1141593, 141500, 25655, '<td valign="top">Nice details, great lighting, wonderful interpretation of the challenge.<br/></td>', 'Nice details, great lighting, wonderful interpretation of the challenge.', '2005-01-31 02:51:42.000000', NULL, 1),
(1141594, 141854, 17507, '<td valign="top">Great idea. I would have loved to see this without the white at the bottom and with a bit less glare on the bubble itself.</td>', 'Great idea. I would have loved to see this without the white at the bottom and with a bit less glare on the bubble itself.', '2005-01-31 02:53:18.000000', NULL, 1),
(1141595, 141786, 25655, '<td valign="top">Obviously many feathers in this challenge but somehow I do not get tired of those.<br/>Wonderful picture, beautiful soft lighting with great details.<br/>Very nicely done!</td>', 'Obviously many feathers in this challenge but somehow I do not get tired of those.Wonderful picture, beautiful soft lighting with great details.Very nicely done!', '2005-01-31 02:53:50.000000', NULL, 1),
(1141597, 141870, 28619, '<td valign="top">She is a great looking chick but I''m not keen on the expression on her face.</td>', 'She is a great looking chick but I''m not keen on the expression on her face.', '2005-01-31 03:00:07.000000', NULL, 1),
(1141599, 141887, 17507, '<td valign="top">Great capture- could you have possibly burned in the mountain a bit so it isn''t so blown out? I think that would have helped a lot.</td>', 'Great capture- could you have possibly burned in the mountain a bit so it isn''t so blown out? I think that would have helped a lot.', '2005-01-31 03:01:27.000000', NULL, 1),
(1141600, 141063, 29241, '<td valign="top">Very NIce!</td>', 'Very NIce!', '2005-01-31 03:01:28.000000', NULL, 1),
(1141601, 141476, 28619, '<td valign="top">This looks like a spot I know well as it was the subject for my first challenge entry.  This one is a lot better than my attempt.</td>', 'This looks like a spot I know well as it was the subject for my first challenge entry.  This one is a lot better than my attempt.', '2005-01-31 03:03:24.000000', NULL, 1),
(1141603, 141534, 28619, '<td valign="top">I find that only one eye being visible makes me feel unseasy.  Don''t know why, but I would like to see some of the other eye too.</td>', 'I find that only one eye being visible makes me feel unseasy.  Don''t know why, but I would like to see some of the other eye too.', '2005-01-31 03:06:35.000000', NULL, 1),
(1141605, 140567, 28619, '<td valign="top">Oh dear, this is WAY too small and will get marked down severely for that reason.<br/> <br/>The photo itself is puzzling.  What is it?  It just looks like a blur.</td>', 'Oh dear, this is WAY too small and will get marked down severely for that reason. The photo itself is puzzling.  What is it?  It just looks like a blur.', '2005-01-31 03:09:14.000000', NULL, 1),
(1141607, 141795, 28619, '<td valign="top">Can''t see an obvious link to the challenge.  Nice rode though.</td>', 'Can''t see an obvious link to the challenge.  Nice rode though.', '2005-01-31 03:09:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1141611, 141826, 28619, '<td valign="top">No offence but that blister or whatever it is on the left big toe really puts me off.  I don''t think pictures of feet are going to do well on this site.</td>', 'No offence but that blister or whatever it is on the left big toe really puts me off.  I don''t think pictures of feet are going to do well on this site.', '2005-01-31 03:14:26.000000', NULL, 1),
(1141615, 139647, 23300, '<td valign="top">This image speaks to me of silent or passive energy. The lighting highlights his face perfectly and the harsh light at the bottom adds to the power of the image. It would make a good cover  image for a book on The Tao or something like that. The duotone really enhances the impact of the lighting. The more I write the more I like it. Good Luck.</td>', 'This image speaks to me of silent or passive energy. The lighting highlights his face perfectly and the harsh light at the bottom adds to the power of the image. It would make a good cover  image for a book on The Tao or something like that. The duotone really enhances the impact of the lighting. The more I write the more I like it. Good Luck.', '2005-01-31 03:30:51.000000', NULL, 1),
(1141617, 141513, 16301, '<td valign="top">Oh my god, so very artistic, I love it! The slight tilt makes it ten times dynamic. +fav</td>', 'Oh my god, so very artistic, I love it! The slight tilt makes it ten times dynamic. +fav', '2005-01-31 03:31:02.000000', NULL, 1),
(1141618, 141417, 23300, '<td valign="top">The title of this image really sets a great tone for interpreting the image. The light really does make the mundane task look almost peaceful and joyful. I love the way that the main subject, the man, is on the dividing line between dark and light. The muted colours add to the "delicacy" of the image and the light catching the broom handle all the way along strengthens the composition so much.  Beautiful.</td>', 'The title of this image really sets a great tone for interpreting the image. The light really does make the mundane task look almost peaceful and joyful. I love the way that the main subject, the man, is on the dividing line between dark and light. The muted colours add to the "delicacy" of the image and the light catching the broom handle all the way along strengthens the composition so much.  Beautiful.', '2005-01-31 03:37:54.000000', NULL, 1),
(1141621, 140925, 23300, '<td valign="top">I love the concept and tonality of this image. I do feel it would be strengthened if it was cropped to move the light to the right and up a bit and then to remove some off the bottom of the image. This would push the light to about a third in from the right and about a third from the top which I think would enhance the mood produced by the image. Having said that, I love the simplicity  and style of this image. Its amazingly evocative. Good Luck with the challenge.</td>', 'I love the concept and tonality of this image. I do feel it would be strengthened if it was cropped to move the light to the right and up a bit and then to remove some off the bottom of the image. This would push the light to about a third in from the right and about a third from the top which I think would enhance the mood produced by the image. Having said that, I love the simplicity  and style of this image. Its amazingly evocative. Good Luck with the challenge.', '2005-01-31 03:42:56.000000', NULL, 1),
(1141626, 141897, 27318, '<td valign="top">The border has got to go.</td>', 'The border has got to go.', '2005-01-31 03:45:58.000000', NULL, 1),
(1141631, 141723, 19959, '<td valign="top">Nice idea, I am not sure that the drop-off of light towards the left works particularly well though.</td>', 'Nice idea, I am not sure that the drop-off of light towards the left works particularly well though.', '2005-01-31 03:55:25.000000', NULL, 1),
(1141632, 140825, 19959, '<td valign="top">Nice idea..</td>', 'Nice idea..', '2005-01-31 03:56:27.000000', NULL, 1),
(1141637, 141305, 32602, '<td valign="top">Cute idea.</td>', 'Cute idea.', '2005-01-31 04:09:54.000000', NULL, 1),
(1141639, 141817, 32602, '<td valign="top">I like this because it suggest different things to me: molten lava,  bubbling tar,<br/>oil wells etc. it has a gritty apeal.</td>', 'I like this because it suggest different things to me: molten lava,  bubbling tar,oil wells etc. it has a gritty apeal.', '2005-01-31 04:12:13.000000', NULL, 1),
(1141641, 141391, 32602, '<td valign="top">Great idea, I think I would prefer  the light bulb to be supported in a less obvious way though.</td>', 'Great idea, I think I would prefer  the light bulb to be supported in a less obvious way though.', '2005-01-31 04:14:06.000000', NULL, 1),
(1141642, 141173, 26679, '<td valign="top">Interesting title. This capture brings warmth to the obviously dying leaves. The balance works well, and the bokeh introduces spots of light in the background.<br/>A slightly sharper focus on the leaves would lift this another lovel.</td>', 'Interesting title. This capture brings warmth to the obviously dying leaves. The balance works well, and the bokeh introduces spots of light in the background.A slightly sharper focus on the leaves would lift this another lovel.', '2005-01-31 04:14:09.000000', NULL, 1),
(1141646, 139438, 32164, '<td valign="top">great photo, great light</td>', 'great photo, great light', '2005-01-31 04:20:49.000000', NULL, 1),
(1141651, 141704, 15832, '<td valign="top">Very nice!!  The tillt is just a littel off but you get a 8 from me.<br/> <br/></td>', 'Very nice!!  The tillt is just a littel off but you get a 8 from me. ', '2005-01-31 04:26:56.000000', NULL, 1),
(1141653, 141608, 15832, '<td valign="top">That´s a great picture!<br/>The buttom of the photo is sturfing me.. Is it ice?<br/>7</td>', 'That´s a great picture!The buttom of the photo is sturfing me.. Is it ice?7', '2005-01-31 04:28:48.000000', NULL, 1),
(1141655, 141898, 15832, '<td valign="top">Wow.... That´s amazing.. How did you do that???   I have to know?<br/>I love it how you locate the subjeckt and where he is looking. The cap makes this macigal atmosphere and the shadow is perfeckt..<br/>10 from me and straight in my favorite....</td>', 'Wow.... That´s amazing.. How did you do that???   I have to know?I love it how you locate the subjeckt and where he is looking. The cap makes this macigal atmosphere and the shadow is perfeckt..10 from me and straight in my favorite....', '2005-01-31 04:35:04.000000', NULL, 1),
(1141658, 141682, 15832, '<td valign="top">Nice angel from the light. 6</td>', 'Nice angel from the light. 6', '2005-01-31 04:38:28.000000', NULL, 1),
(1141660, 141513, 15832, '<td valign="top">Very nice.. I like the tillt, the shadows and light is great</td>', 'Very nice.. I like the tillt, the shadows and light is great', '2005-01-31 04:40:17.000000', NULL, 1),
(1141669, 141597, 16004, '<td valign="top">other than the title, it would be impossible to tell your method of lighting - indeed, the light feels oddly cold for something coming from a natural flame.  though it doesn''t bother me, i fear you might get a bit of a bashing for your model not showing his eyes (apparently it''s rule #1 in portraiture).  it''s nicely composed, but it doesn''t really get much emotion / feeling out of me.  6.</td>', 'other than the title, it would be impossible to tell your method of lighting - indeed, the light feels oddly cold for something coming from a natural flame.  though it doesn''t bother me, i fear you might get a bit of a bashing for your model not showing his eyes (apparently it''s rule #1 in portraiture).  it''s nicely composed, but it doesn''t really get much emotion / feeling out of me.  6.', '2005-01-31 04:48:02.000000', NULL, 1),
(1141676, 140911, 19405, '<td valign="top">I like the topic. Ilike the evil looking light. It is a bit blurry though.</td>', 'I like the topic. Ilike the evil looking light. It is a bit blurry though.', '2005-01-31 04:59:42.000000', NULL, 1),
