(1141697, 140012, 19405, '<td valign="top">Fantastic!</td>', 'Fantastic!', '2005-01-31 05:12:30.000000', NULL, 1),
(1141698, 141706, 17233, '<td valign="top">There seems to be little contrast in the subject. Good attempt at highkey though. Try upping the contrast  and you may find that it begins to pop by blowing out the distracting remnants across the top and bringing the subject to life.</td>', 'There seems to be little contrast in the subject. Good attempt at highkey though. Try upping the contrast  and you may find that it begins to pop by blowing out the distracting remnants across the top and bringing the subject to life.', '2005-01-31 05:13:14.000000', NULL, 1),
(1141699, 141894, 19405, '<td valign="top">Fantastic frame.</td>', 'Fantastic frame.', '2005-01-31 05:14:19.000000', NULL, 1),
