(1145840, 139475, 32885, '<td valign="top">Nice subject but personally I would have preferred to see the light coming from the lighthouse.</td>', 'Nice subject but personally I would have preferred to see the light coming from the lighthouse.', '2005-02-02 05:22:27.000000', NULL, 1),
(1145841, 139837, 32885, '<td valign="top">Very interesting</td>', 'Very interesting', '2005-02-02 05:23:02.000000', NULL, 1),
(1145843, 141786, 32885, '<td valign="top">Very cute theme but not quite what I thought was intended.</td>', 'Very cute theme but not quite what I thought was intended.', '2005-02-02 05:24:36.000000', NULL, 1),
(1145847, 141347, 32885, '<td valign="top">I like this photo. A bit of imagination has gone into it.</td>', 'I like this photo. A bit of imagination has gone into it.', '2005-02-02 05:26:34.000000', NULL, 1),
