(1145859, 141794, 32885, '<td valign="top">Nice theme but it is let down by the lack of clarity of the bannister at the top of the stairs.</td>', 'Nice theme but it is let down by the lack of clarity of the bannister at the top of the stairs.', '2005-02-02 05:33:42.000000', NULL, 1),
