(1145932, 141760, 32885, '<td valign="top">Nice colours.</td>', 'Nice colours.', '2005-02-02 06:32:11.000000', NULL, 1),
(1145944, 139653, 32885, '<td valign="top">A great composition. Well spotted in nature. The photographer must have a great imagination to see the potential of this setting. Well done.</td>', 'A great composition. Well spotted in nature. The photographer must have a great imagination to see the potential of this setting. Well done.', '2005-02-02 06:45:09.000000', NULL, 1),
