(1145949, 140322, 27524, '<td valign="top">Interesting abstract capture... i like the play with shapes and lights.</td>', 'Interesting abstract capture... i like the play with shapes and lights.', '2005-02-02 06:49:12.000000', NULL, 1),
(1145957, 141518, 27524, '<td valign="top">Very beautiful portrait bit soft but nice colors.</td>', 'Very beautiful portrait bit soft but nice colors.', '2005-02-02 06:51:29.000000', NULL, 1),
