(1148777, 141829, 18485, '<td valign="top">it does not get better than this.  excellent shot.  beautiful realization of the challenge.  great stuff.  thanks for sharing.</td>', 'it does not get better than this.  excellent shot.  beautiful realization of the challenge.  great stuff.  thanks for sharing.', '2005-02-03 11:38:48.000000', NULL, 1),
