INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1148817, 141465, 2490, '<td valign="top">The border is a detriment in this case :(  Sorry.</td>', 'The border is a detriment in this case :(  Sorry.', '2005-02-03 12:01:11.000000', NULL, 1),
(1148927, 141663, 22384, '<td valign="top">Stunning image and great double-entendre. So true. So beautiful. Great Shot - 10</td>', 'Stunning image and great double-entendre. So true. So beautiful. Great Shot - 10', '2005-02-03 13:18:32.000000', NULL, 1),
(1148931, 141729, 22384, '<td valign="top">Nice light on the subjects hand. The burned or shadow section under the arm makes your subject look skeletal. It does not align with the muscle definition on the upper side of the arm.</td>', 'Nice light on the subjects hand. The burned or shadow section under the arm makes your subject look skeletal. It does not align with the muscle definition on the upper side of the arm.', '2005-02-03 13:19:59.000000', NULL, 1),
(1148932, 141116, 22384, '<td valign="top">I have seen a similar shot. It is an interesting effect.</td>', 'I have seen a similar shot. It is an interesting effect.', '2005-02-03 13:20:43.000000', NULL, 1),
(1148933, 141781, 22384, '<td valign="top">Creative shot. Since it is so geometrical, I would like to see the center in crisp focus. The white in the upper left hand corner is a bit distracting, but other than than I like the crop.</td>', 'Creative shot. Since it is so geometrical, I would like to see the center in crisp focus. The white in the upper left hand corner is a bit distracting, but other than than I like the crop.', '2005-02-03 13:22:23.000000', NULL, 1),
(1148934, 141809, 22384, '<td valign="top">Great Shadows. Creative shot. My mind is seeking a focal point, but I think that is because the shot seems to be an optical illusion. Very creative! 8</td>', 'Great Shadows. Creative shot. My mind is seeking a focal point, but I think that is because the shot seems to be an optical illusion. Very creative! 8', '2005-02-03 13:23:38.000000', NULL, 1),
(1148935, 141902, 22384, '<td valign="top">I love this. Great texture in the snow and wonderful job of composition. Your images carries my eye and mind off into the night. Brilliant capture. You are an artist and a photographer - This image transcends for me! 9</td>', 'I love this. Great texture in the snow and wonderful job of composition. Your images carries my eye and mind off into the night. Brilliant capture. You are an artist and a photographer - This image transcends for me! 9', '2005-02-03 13:25:12.000000', NULL, 1),
(1148937, 141561, 22384, '<td valign="top">I like the texture of this shot. I am uncomfortable with the crop. My eye longs to see more at the top of the image and less at the bottom. Nice job with the snow. It is so difficult to shoot snow in the sunlight. You have a couple of blown out whites, but overall the snow works well in this image.</td>', 'I like the texture of this shot. I am uncomfortable with the crop. My eye longs to see more at the top of the image and less at the bottom. Nice job with the snow. It is so difficult to shoot snow in the sunlight. You have a couple of blown out whites, but overall the snow works well in this image.', '2005-02-03 13:27:07.000000', NULL, 1),
(1148939, 139612, 22384, '<td valign="top">Great capture. Something about this image reminds me of Armstrong''s walk on the moon ;-). This is top notch! 9</td>', 'Great capture. Something about this image reminds me of Armstrong''s walk on the moon ;-). This is top notch! 9', '2005-02-03 13:28:34.000000', NULL, 1),
(1148940, 141706, 22384, '<td valign="top">Beautiful subject. The image is too washed out, though. Burn some of the essentials (flowers, hand, face) and see what you think.<br/></td>', 'Beautiful subject. The image is too washed out, though. Burn some of the essentials (flowers, hand, face) and see what you think.', '2005-02-03 13:29:40.000000', NULL, 1),
(1148943, 141355, 22384, '<td valign="top">I like the colors and the idea. This image is too busy, though. I think it would have worked well with just one candle and no reflections. The soft focus of the reflected candles muddles the image.</td>', 'I like the colors and the idea. This image is too busy, though. I think it would have worked well with just one candle and no reflections. The soft focus of the reflected candles muddles the image.', '2005-02-03 13:31:12.000000', NULL, 1),
(1148953, 140807, 22384, '<td valign="top">I love shots like this. Nice shallow dof. I am not going to look at it too closely because that ruins an image like this. The power of this shot is its initial impact. I am going to rate it on that. Initial impace -  Stunning. 8</td>', 'I love shots like this. Nice shallow dof. I am not going to look at it too closely because that ruins an image like this. The power of this shot is its initial impact. I am going to rate it on that. Initial impace -  Stunning. 8', '2005-02-03 13:36:32.000000', NULL, 1),
(1148991, 141634, 22384, '<td valign="top">Pretty shot and fun reflection of the colors in the water.</td>', 'Pretty shot and fun reflection of the colors in the water.', '2005-02-03 14:01:06.000000', NULL, 1),
(1148998, 139620, 22384, '<td valign="top">I love this shot. Its initial impact is breathtaking. Great job of evoking a soft, smokey feeling of peacefulness. I know those look like storm clouds, but it still gives me a sense of peace and hope. The use of the line in the shadows to draw your viewer''s eye is masterful. Brilliant - 10</td>', 'I love this shot. Its initial impact is breathtaking. Great job of evoking a soft, smokey feeling of peacefulness. I know those look like storm clouds, but it still gives me a sense of peace and hope. The use of the line in the shadows to draw your viewer''s eye is masterful. Brilliant - 10', '2005-02-03 14:04:18.000000', NULL, 1),
(1149000, 141726, 22384, '<td valign="top">I like the star filter effect, but the shot seems slightly off center and the extra stuff on the right is distracting. I think a tighter crop would have worked wonders.</td>', 'I like the star filter effect, but the shot seems slightly off center and the extra stuff on the right is distracting. I think a tighter crop would have worked wonders.', '2005-02-03 14:05:37.000000', NULL, 1),
