(1151523, 141829, 22970, '<td valign="top">What can I say: Right place at the right time with the right camera and with the right skills. Great Capture 10!</td>', 'What can I say: Right place at the right time with the right camera and with the right skills. Great Capture 10!', '2005-02-05 03:00:59.000000', NULL, 1),
