(1152557, 141850, 31597, '<td valign="top">this picture looks inverted.  well hoever you shot the photo, it looks great,  the contrast and sharpness of this is perfect, not to mention the focus point.</td>', 'this picture looks inverted.  well hoever you shot the photo, it looks great,  the contrast and sharpness of this is perfect, not to mention the focus point.', '2005-02-05 21:49:32.000000', NULL, 1),
(1152560, 141045, 31597, '<td valign="top">i love the softness of the skin in this photo.  the subject is also interesting.  a little broad on the challege ''light'', but hey its a cool photo.</td>', 'i love the softness of the skin in this photo.  the subject is also interesting.  a little broad on the challege ''light'', but hey its a cool photo.', '2005-02-05 21:51:43.000000', NULL, 1),
(1152561, 140882, 31597, '<td valign="top">this is a great picture.  i''m glad that you included the sun in the corner so we know where the light is coming from.  i also like the coloration of the image.</td>', 'this is a great picture.  i''m glad that you included the sun in the corner so we know where the light is coming from.  i also like the coloration of the image.', '2005-02-05 21:54:19.000000', NULL, 1),
(1152563, 141798, 31597, '<td valign="top">wow. this is a perfect example why photographer use photoshop.  you took a pretty picture and made it prettier.  nice.</td>', 'wow. this is a perfect example why photographer use photoshop.  you took a pretty picture and made it prettier.  nice.', '2005-02-05 21:56:37.000000', NULL, 1),
(1152572, 141508, 31597, '<td valign="top">interesting subject and well taken.  the shadows just popout.</td>', 'interesting subject and well taken.  the shadows just popout.', '2005-02-05 22:11:16.000000', NULL, 1),
(1152576, 141899, 21362, '<td valign="top">I''m not sure about the frame, but otherwise this is kind of interesting.</td>', 'I''m not sure about the frame, but otherwise this is kind of interesting.', '2005-02-05 22:16:51.000000', NULL, 1),
(1152580, 141398, 31597, '<td valign="top">ummmm...this picture looks too staged and although it goes along with the challenge subject, it is too streotypical.   suggestion: get a clear bulb and stick the feathers in it.</td>', 'ummmm...this picture looks too staged and although it goes along with the challenge subject, it is too streotypical.   suggestion: get a clear bulb and stick the feathers in it.', '2005-02-05 22:24:58.000000', NULL, 1),
(1152582, 141847, 21362, '<td valign="top">I think I would have stepped up in front of those benches and tree branches. The beautiful colors in the sky and the reflections on the ice are interesting enough. The foreground elements seem a bit like clutter to me.</td>', 'I think I would have stepped up in front of those benches and tree branches. The beautiful colors in the sky and the reflections on the ice are interesting enough. The foreground elements seem a bit like clutter to me.', '2005-02-05 22:27:05.000000', NULL, 1),
(1152585, 139697, 21362, '<td valign="top">A pretty scene that woul''ve been bettwer without those rooftops. Really nice color and light though.</td>', 'A pretty scene that woul''ve been bettwer without those rooftops. Really nice color and light though.', '2005-02-05 22:28:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1152590, 141881, 31597, '<td valign="top">i''m glade that you put a border on this photo.  the lights turned out good as well.</td>', 'i''m glade that you put a border on this photo.  the lights turned out good as well.', '2005-02-05 22:31:42.000000', NULL, 1),
(1152591, 141512, 21362, '<td valign="top">Pretty image. I think having both the foreground grass AND the skaters is a bit busy though. A pure landscape with just the grass would be nice. Or moving somewhere where you could get the skaters better would make a nice photo.<br/> <br/>Still good though. I like the pinkish monotone feel it has. Looks like a fun evening for those kids. :)</td>', 'Pretty image. I think having both the foreground grass AND the skaters is a bit busy though. A pure landscape with just the grass would be nice. Or moving somewhere where you could get the skaters better would make a nice photo. Still good though. I like the pinkish monotone feel it has. Looks like a fun evening for those kids. :)', '2005-02-05 22:32:08.000000', NULL, 1),
(1152594, 141514, 21362, '<td valign="top">Doesn''t ring true to me, a sky with that much light *and* stars at the same time. Pretty though, even if a bit artificial.</td>', 'Doesn''t ring true to me, a sky with that much light *and* stars at the same time. Pretty though, even if a bit artificial.', '2005-02-05 22:34:44.000000', NULL, 1),
(1152599, 141704, 21362, '<td valign="top">Nice but would be better if uncentered and maybe taken from a lower point-of-view rather than the usual standing height. Kneel and aim slightly up, getting more of the interesting pattern on the roof. Also maybe a person just about to walk into the bright light might add interest (or seem too cliche...)<br/> <br/>Nice exposure and color.</td>', 'Nice but would be better if uncentered and maybe taken from a lower point-of-view rather than the usual standing height. Kneel and aim slightly up, getting more of the interesting pattern on the roof. Also maybe a person just about to walk into the bright light might add interest (or seem too cliche...) Nice exposure and color.', '2005-02-05 22:41:20.000000', NULL, 1),
(1152604, 140882, 21362, '<td valign="top">Beautiful. Makes me wish I was there. :)</td>', 'Beautiful. Makes me wish I was there. :)', '2005-02-05 22:44:13.000000', NULL, 1),
(1152608, 141843, 21362, '<td valign="top">Pretty pastels and I really like the effect of the deep foreground. Might be slightly more effective if you could''ve stood on something high and gotten just a bit more of the water. It''s such a narrow little band there. But very good.</td>', 'Pretty pastels and I really like the effect of the deep foreground. Might be slightly more effective if you could''ve stood on something high and gotten just a bit more of the water. It''s such a narrow little band there. But very good.', '2005-02-05 22:47:11.000000', NULL, 1),
(1152611, 141417, 21362, '<td valign="top">A bit too centered. I like the subject though, and the light exposure.</td>', 'A bit too centered. I like the subject though, and the light exposure.', '2005-02-05 22:48:53.000000', NULL, 1),
(1152614, 141817, 21362, '<td valign="top">Love that song!<br/> <br/>Pretty image too.</td>', 'Love that song! Pretty image too.', '2005-02-05 22:49:49.000000', NULL, 1),
(1152616, 141212, 21362, '<td valign="top">Wow, gorgeous pink light!</td>', 'Wow, gorgeous pink light!', '2005-02-05 22:50:59.000000', NULL, 1),
(1152630, 140161, 31213, '<td valign="top">Interesting take on the word "light",  Nice composure.  I like how the subject is off center with breathing room on the left side of the frame.  I think if the man playing the guitar were a little more out of focus he wouldn''t be quite as distracting.  I like thim....he''s interesting....but I find my gaze foloowing him (the action).  Nice capture!  Keep up the great work and I hope you do well.  8!</td>', 'Interesting take on the word "light",  Nice composure.  I like how the subject is off center with breathing room on the left side of the frame.  I think if the man playing the guitar were a little more out of focus he wouldn''t be quite as distracting.  I like thim....he''s interesting....but I find my gaze foloowing him (the action).  Nice capture!  Keep up the great work and I hope you do well.  8!', '2005-02-05 23:08:24.000000', NULL, 1),
(1152634, 140926, 31213, '<td valign="top">Wow...this is very nice.  I''d love to hear exactly how you did this...I have my guesses....but I''d like to know for sure.  The feather on the far right is a little hot....but I can see how it''d be tough to get this perfect.  Great shot!  Should do well.</td>', 'Wow...this is very nice.  I''d love to hear exactly how you did this...I have my guesses....but I''d like to know for sure.  The feather on the far right is a little hot....but I can see how it''d be tough to get this perfect.  Great shot!  Should do well.', '2005-02-05 23:10:42.000000', NULL, 1),
(1152640, 141486, 31213, '<td valign="top">This has great potential...but the light isn''t consistent with the action.  Notice the lid of the box is not fully opened.  If the light on her face was really coming from the box....there would be a diagonal shodow from the lid accross her face.  Also I wish the wall behind her were black.  Nice shot and idea though.</td>', 'This has great potential...but the light isn''t consistent with the action.  Notice the lid of the box is not fully opened.  If the light on her face was really coming from the box....there would be a diagonal shodow from the lid accross her face.  Also I wish the wall behind her were black.  Nice shot and idea though.', '2005-02-05 23:13:08.000000', NULL, 1),
(1152641, 139620, 29477, '<td valign="top">wonderful atmosphere created here...this shot is worthy of a high finish in this challenge...very powerful...</td>', 'wonderful atmosphere created here...this shot is worthy of a high finish in this challenge...very powerful...', '2005-02-05 23:13:30.000000', NULL, 1),
(1152642, 141513, 21362, '<td valign="top">Moody. I like it a lot. I''m such a sucker for strong shadows and I like the unusual angle too. Good shot! Giving it a 10 and adding to my favorites. :)</td>', 'Moody. I like it a lot. I''m such a sucker for strong shadows and I like the unusual angle too. Good shot! Giving it a 10 and adding to my favorites. :)', '2005-02-05 23:14:39.000000', NULL, 1),
(1152650, 141798, 29477, '<td valign="top">Beautiful image, but is too overprocessed for my liking.</td>', 'Beautiful image, but is too overprocessed for my liking.', '2005-02-05 23:22:17.000000', NULL, 1),
(1152660, 141875, 29477, '<td valign="top">The use of your flash takes away from the lights in behind...A tripod and larger exposure time would have streghtened this shot as it is nicely composed.</td>', 'The use of your flash takes away from the lights in behind...A tripod and larger exposure time would have streghtened this shot as it is nicely composed.', '2005-02-05 23:31:56.000000', NULL, 1),
(1152669, 141699, 29477, '<td valign="top">Nicely composed image, however the border is killing the result.</td>', 'Nicely composed image, however the border is killing the result.', '2005-02-05 23:42:05.000000', NULL, 1),
(1152671, 141887, 11756, '<td valign="top">nice photo.  would have cropped the top, but the rock stasnds out nicely</td>', 'nice photo.  would have cropped the top, but the rock stasnds out nicely', '2005-02-05 23:43:26.000000', NULL, 1),
(1152673, 141500, 29477, '<td valign="top">Would have like to seen this image not so tightly cropped and framed to include the long shadow of the feather.  This would have been more impactful to me...Still a nice shot, simple and effective.</td>', 'Would have like to seen this image not so tightly cropped and framed to include the long shadow of the feather.  This would have been more impactful to me...Still a nice shot, simple and effective.', '2005-02-05 23:50:40.000000', NULL, 1),
(1152679, 141201, 29477, '<td valign="top">Simple and effective...A great shot in my books. Well done.</td>', 'Simple and effective...A great shot in my books. Well done.', '2005-02-05 23:58:49.000000', NULL, 1),
(1152705, 141500, 23025, '<td valign="top">fantastic</td>', 'fantastic', '2005-02-06 00:27:20.000000', NULL, 1),
(1152729, 141465, 4767, '<td valign="top">The white frame with the black border makes it look more like a snapshot, which IMNHO weakens a very powerful photo.</td>', 'The white frame with the black border makes it look more like a snapshot, which IMNHO weakens a very powerful photo.', '2005-02-06 00:44:32.000000', NULL, 1),
(1152795, 141759, 21202, '<td valign="top">You are right.  This looks better at this brightness.  I thought it might be better darker, but not so.  Very lovely.  A 9.</td>', 'You are right.  This looks better at this brightness.  I thought it might be better darker, but not so.  Very lovely.  A 9.', '2005-02-06 02:10:45.000000', NULL, 1),
(1152797, 141787, 16521, '<td valign="top">Wonderful shot!</td>', 'Wonderful shot!', '2005-02-06 02:11:59.000000', NULL, 1),
(1152801, 141709, 6477, '<td valign="top">so beautifu modell:) this is a great shot, and I like that the light source is in front of your model... good luck...</td>', 'so beautifu modell:) this is a great shot, and I like that the light source is in front of your model... good luck...', '2005-02-06 02:14:12.000000', NULL, 1),
(1152858, 139815, 9668, '<td valign="top">Cool shot, but doesn''t <i>speak</i> to me.</td>', 'Cool shot, but doesn''t speak to me.', '2005-02-06 02:59:41.000000', NULL, 1),
(1152863, 141141, 9668, '<td valign="top">Is that the only title you could think of? What about "Universe Within," "Core," "Central Being." '' Illuminated Object'' just tells us a little bit about the photo that we can already see. &lt;/end mini rant&gt;. Awsome shot! I know it wouldn''t really be possible, but it would be sweet to have a different background that could make it stand out even more. Well done.</td>', 'Is that the only title you could think of? What about "Universe Within," "Core," "Central Being." '' Illuminated Object'' just tells us a little bit about the photo that we can already see. </end mini rant>. Awsome shot! I know it wouldn''t really be possible, but it would be sweet to have a different background that could make it stand out even more. Well done.', '2005-02-06 03:02:38.000000', NULL, 1),
(1152867, 141791, 9668, '<td valign="top">Cool concept, but it seems a bit fuzzy. I like the angle you''ve captured.</td>', 'Cool concept, but it seems a bit fuzzy. I like the angle you''ve captured.', '2005-02-06 03:04:46.000000', NULL, 1),
(1152869, 141212, 9668, '<td valign="top">Stunning! Excellenc capture of the light. Nice reflection off the water, with the ice still layered over some parts.</td>', 'Stunning! Excellenc capture of the light. Nice reflection off the water, with the ice still layered over some parts.', '2005-02-06 03:06:17.000000', NULL, 1),
(1152889, 141840, 9668, '<td valign="top">I like how it give the idea of the light being on without an output. I''m guessing you lit up behind it, but you could have created some direct energy transfer straight into the lightbulb =).<br/> I like the title but I have a few problems with it. You are suggesting that the center of the universe is isn''t a human made creation: a light bulb. So either humans contain the center of the universe (which is a common mentality), or they have caught it. I disagree. God created the infinate universe, we don''t know where the center is, but it definatly isn''t inside a lightbulb.<br/>Technical: Nice focus and composition. I''m not quiet sure what the background is, but it give a good texture. The gray "shadow" below the light bulb is a bit distracting. The two specs of reflection on top of the lightbulb are a bit distracting as well.</td>', 'I like how it give the idea of the light being on without an output. I''m guessing you lit up behind it, but you could have created some direct energy transfer straight into the lightbulb =). I like the title but I have a few problems with it. You are suggesting that the center of the universe is isn''t a human made creation: a light bulb. So either humans contain the center of the universe (which is a common mentality), or they have caught it. I disagree. God created the infinate universe, we don''t know where the center is, but it definatly isn''t inside a lightbulb.Technical: Nice focus and composition. I''m not quiet sure what the background is, but it give a good texture. The gray "shadow" below the light bulb is a bit distracting. The two specs of reflection on top of the lightbulb are a bit distracting as well.', '2005-02-06 03:16:06.000000', NULL, 1),
(1152893, 141509, 9668, '<td valign="top">I was hoping to catch something like this for this challenge but I didn''t get any. Excellent job with the reflections off the water.</td>', 'I was hoping to catch something like this for this challenge but I didn''t get any. Excellent job with the reflections off the water.', '2005-02-06 03:18:31.000000', NULL, 1),
(1152896, 140322, 9668, '<td valign="top">Taken of a computer monitor? Nice pattern.</td>', 'Taken of a computer monitor? Nice pattern.', '2005-02-06 03:20:53.000000', NULL, 1),
(1152903, 141875, 9668, '<td valign="top">Awsome walkway. I wouldn''t recommend using a flash in this condition though. Maybe if you had a tripod and were about to get a little longer exposure to light up the pillars. Cool catch.</td>', 'Awsome walkway. I wouldn''t recommend using a flash in this condition though. Maybe if you had a tripod and were about to get a little longer exposure to light up the pillars. Cool catch.', '2005-02-06 03:23:44.000000', NULL, 1),
(1152908, 141896, 9668, '<td valign="top">Sure doesn''t look like Saturn to me, course I''ve never been on Saturn, so I wouldn''t know. Was there some secret mission that the USA Gov. doesn''t know about that you were able to photograph saturn and submit it to DPC. <br/> <br/>Awsome shot, nice play of foreground and background.</td>', 'Sure doesn''t look like Saturn to me, course I''ve never been on Saturn, so I wouldn''t know. Was there some secret mission that the USA Gov. doesn''t know about that you were able to photograph saturn and submit it to DPC.  Awsome shot, nice play of foreground and background.', '2005-02-06 03:26:51.000000', NULL, 1),
(1152941, 141890, 9668, '<td valign="top">Wow, I like how this photo shows the essence of the existenstinial being. It shows the search we all have for the truth that lies in the core of our souls if we had to time to stop and find it. <br/> <br/>Well, interesting shot, I can''t really see anything defined, but it is a different take on this challenge.</td>', 'Wow, I like how this photo shows the essence of the existenstinial being. It shows the search we all have for the truth that lies in the core of our souls if we had to time to stop and find it.  Well, interesting shot, I can''t really see anything defined, but it is a different take on this challenge.', '2005-02-06 03:59:12.000000', NULL, 1),
(1152942, 141787, 9668, '<td valign="top">Poster board? Awsome setup, nicely lit.</td>', 'Poster board? Awsome setup, nicely lit.', '2005-02-06 03:59:49.000000', NULL, 1),
(1152955, 141818, 19729, '<td valign="top">good idea, good light , good compose ,perfect shot. thanx</td>', 'good idea, good light , good compose ,perfect shot. thanx', '2005-02-06 04:07:02.000000', NULL, 1),
(1152956, 140227, 19729, '<td valign="top">good shot , good rainbow, i like it. thank</td>', 'good shot , good rainbow, i like it. thank', '2005-02-06 04:08:41.000000', NULL, 1),
