(1153743, 141156, 21362, '<td valign="top">Sort of cool effect I guess, but not really memorable as a photograph.</td>', 'Sort of cool effect I guess, but not really memorable as a photograph.', '2005-02-06 20:56:45.000000', NULL, 1),
