(1192385, 141112, 27922, '<td valign="top">I really want some marshmellows to eat because of this photo. Got milk!</td>', 'I really want some marshmellows to eat because of this photo. Got milk!', '2005-02-24 09:05:29.000000', NULL, 0),
(1193712, 141465, 25952, '<td valign="top">i think this is pretty underrated.</td>', 'i think this is pretty underrated.', '2005-02-25 02:00:47.000000', NULL, 0),
(1208670, 139620, 32285, '<td valign="top">Very cool shot! Love the mysterious mood this has! EXCELLENT work!:)</td>', 'Very cool shot! Love the mysterious mood this has! EXCELLENT work!:)', '2005-03-04 23:03:59.000000', NULL, 0),
(1209931, 141535, 32285, '<td valign="top">Wonderful shot! Great backlighting and comp.</td>', 'Wonderful shot! Great backlighting and comp.', '2005-03-05 23:58:08.000000', NULL, 0),
(1214629, 141843, 8682, '<td valign="top">That´s just excellent!</td>', 'That´s just excellent!', '2005-03-08 10:06:53.000000', NULL, 0),
(1225932, 141798, 2798, '<td valign="top">Wow - now this is an image that makes an impact. It reminds me of that awful Robin Williams movie "What Dreams May Come". It has an impressionistic style to it that I rather like.<br/> <br/>It''s an acceptable if not startlingly interesting scene but it''s the post processing that make this shot an event. It would have been nice to see more light or more lightness on the front of the house to help that detail there. The sky is interesting but a little too hot on the left. The golden foreground is just stunning.<br/> <br/>As an experimental shot I think there''s a lot to enjoy about this and I hope you''ll keep experimenting in this way.</td>', 'Wow - now this is an image that makes an impact. It reminds me of that awful Robin Williams movie "What Dreams May Come". It has an impressionistic style to it that I rather like. It''s an acceptable if not startlingly interesting scene but it''s the post processing that make this shot an event. It would have been nice to see more light or more lightness on the front of the house to help that detail there. The sky is interesting but a little too hot on the left. The golden foreground is just stunning. As an experimental shot I think there''s a lot to enjoy about this and I hope you''ll keep experimenting in this way.', '2005-03-14 05:01:00.000000', NULL, 0),
(1266500, 141817, 13749, '<td valign="top">a great eye you have - wish i had seen this a long time ago as it is definitely among the favorites of my favorites :)</td>', 'a great eye you have - wish i had seen this a long time ago as it is definitely among the favorites of my favorites :)', '2005-04-02 19:34:40.000000', NULL, 0),
(1266506, 141817, 11793, '<td valign="top">i''ve looked at this photo too many times for it not to be a favorite...<br/> <br/></td>', 'i''ve looked at this photo too many times for it not to be a favorite... ', '2005-04-02 19:41:53.000000', NULL, 0),
(1266723, 141817, 20779, '<td valign="top">This is truly awesome, Sher. I am so glad I found this today ( along with quite a few others!!!).</td>', 'This is truly awesome, Sher. I am so glad I found this today ( along with quite a few others!!!).', '2005-04-02 22:06:19.000000', NULL, 0),
