(1455401, 141514, 15711, '<td valign="top">Love the stars.  Unusual to see moonlight with that color configuration. Very imaginative.  Super rich tones!!  Good one.</td>', 'Love the stars.  Unusual to see moonlight with that color configuration. Very imaginative.  Super rich tones!!  Good one.', '2005-06-14 18:03:54.000000', NULL, 0),
(1460030, 141512, 15711, '<td valign="top">This evokes such a calm "end of the day" mood.  Very nice use of color and your composition is really nice!</td>', 'This evokes such a calm "end of the day" mood.  Very nice use of color and your composition is really nice!', '2005-06-16 09:30:39.000000', NULL, 0),
